@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1071  cases=46
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cm:get, am:resizeTake, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui)  @ 47-55
  @fn twoSelected(h)  @ 59-78
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 82-92
  @case 'focusState before any render returns both bits false'  [harness]  @ 96-103
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 107-114
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 118-129
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 133-156
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 160-171
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 175-194
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 198-220
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 224-238
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 242-257
  @case 'arrangeGrowTake lengthens the cursor take by one row'  [harness]  @ 261-278
  @case 'arrangeGrowTake silently no-ops at the take-source length cap'  [harness]  @ 282-296
  @case 'arrangeShrinkTake reduces the cursor take by one row'  [harness]  @ 300-315
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 319-333
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 339-363
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 367-383
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 387-403
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 407-421
  @case 'arrangeGrowTake against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 425-443
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 447-467
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 471-493
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 497-512
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 516-531
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 535-549
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 553-565
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 569-587
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 591-609
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 613-630
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 634-649
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 653-671
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 675-692
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 696-710
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 719-732
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 736-749
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 753-769
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 773-791
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 795-826
  @case 'arrangeDuplicateUnpooledBelow mints a fresh-pool clone and auto-opens take-props'  [harness]  @ 830-848
  @case 'arrangeDuplicateUnpooledBelow parks the clone for want of room, and still names it'  [harness]  @ 852-873
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 879-906
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 910-927
  @case 'the replacements become the selection'  [harness]  @ 931-943
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 947-975
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 979-1007
  @case 'a cursor move disarms replace mode'  [harness]  @ 1011-1037
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1041-1068

